import assert from 'node:assert/strict';
import {existsSync,unlinkSync} from 'node:fs';
import {Client,base,requests,server,setActions,tool,until,delay} from './codex-fixture';
const c=new Client(base+'/controls-baseline-'+Date.now(),true,'',false);const marker=base+'/approved-marker';if(existsSync(marker))unlinkSync(marker);
const question=()=>tool('request_user_input',{questions:[{id:'choice',header:'Choice',question:'Offline choice?',options:[{label:'A',description:'first'},{label:'B',description:'second'}]}]});
const plan={mode:'plan',settings:{model:'gpt-5.1-codex',reasoning_effort:'low',developer_instructions:null}};
try{await c.init();const {thread}=await c.start({approvalPolicy:'untrusted',sandbox:'workspace-write'});
 setActions(tool('exec_command',{cmd:'echo approved > '+marker,login:false}));let {turn}=await c.turn(thread.id,'offline approval');await until(()=>c.serverRequests.some(r=>r.method==='item/commandExecution/requestApproval'),'approval');let req=c.serverRequests.find(r=>r.method==='item/commandExecution/requestApproval');assert.equal(req.params.turnId,turn.id);assert.equal(req.params.threadId,thread.id);assert.equal(existsSync(marker),false);c.reply(req.id,{decision:'accept'});assert.equal((await c.done(turn.id)).status,'completed');assert.equal(existsSync(marker),true);
 setActions(question());({turn}=await c.turn(thread.id,'offline question',{collaborationMode:plan}));await until(()=>c.serverRequests.some(r=>r.method==='item/tool/requestUserInput'&&r.params.turnId===turn.id),'question');req=c.serverRequests.find(r=>r.method==='item/tool/requestUserInput'&&r.params.turnId===turn.id);c.reply(req.id,{answers:{choice:{answers:['A']}}});assert.equal((await c.done(turn.id)).status,'completed');assert.ok(requests.some(r=>r.input?.some((i:any)=>i.type==='function_call_output'&&i.output.includes('"answers":["A"]'))));
 setActions(question());({turn}=await c.turn(thread.id,'cancel pending question',{collaborationMode:plan}));await until(()=>c.serverRequests.some(r=>r.method==='item/tool/requestUserInput'&&r.params.turnId===turn.id));req=c.serverRequests.find(r=>r.method==='item/tool/requestUserInput'&&r.params.turnId===turn.id);await c.call('turn/interrupt',{threadId:thread.id,turnId:turn.id});assert.equal((await c.done(turn.id)).status,'interrupted');await until(()=>c.events.some(e=>e.method==='serverRequest/resolved'&&e.params.requestId===req.id),'resolved cancelled request');const before=requests.filter(r=>r.generate!==false).length;c.reply(req.id,{answers:{choice:{answers:['B']}}});await delay(200);assert.equal(requests.filter(r=>r.generate!==false).length,before);({turn}=await c.turn(thread.id,'fresh after cancelled question'));assert.equal((await c.done(turn.id)).status,'completed');console.log(JSON.stringify({case:'Codex-native-approval-question',approvalScopedAndJoined:true,questionAnswerForwarded:true,cancelClearsPendingQuestion:true,lateAnswerNoExecution:true,freshInputWorks:true}));
}finally{await c.close();server.stop(true)}
